/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by tools/sympy-corpus/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, AppliedUndef, DFT, Dummy, Float, FunctionMatrix, I, IDFT, KroneckerDelta, Lambda, MatPow, Mul, Q, Rational, Sym, abs, add, ask, dummyEq, symbols } from '../../../src';
import { sympyMatches, sympyStr } from '../../sympy-str';

describe("doctests of sympy.matrices.expressions.funcmatrix", () => {
  it("FunctionMatrix(n, m, Lambda((i, j), i + j))", () => {
    const [n, m, i, j] = symbols('n m i j');
    expect(sympyStr(FunctionMatrix(n, m, Lambda([i, j], add(i, j))))).toBe('FunctionMatrix(n, m, Lambda((i, j), i + j))');
  });
  it("X.as_explicit()", () => {
    expect(sympyStr(FunctionMatrix(Rational.of(3n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), Lambda([new Dummy('i', {}, 1000000), new Dummy('j', {}, 1000001)], KroneckerDelta(new Dummy('i', {}, 1000000), new Dummy('j', {}, 1000001)))).asExplicit())).toBe('Matrix([[1, 0, 0], [0, 1, 0], [0, 0, 1]])');
  });
  it("X.as_explicit() (2)", () => {
    expect(sympyStr(FunctionMatrix(Rational.of(3n, 1n, { gcd: 1n }), Rational.of(3n, 1n, { gcd: 1n }), Lambda([new Dummy('i', {}, 1000000), new Dummy('j', {}, 1000001)], new AppliedUndef('f', [new Dummy('i', {}, 1000000), new Dummy('j', {}, 1000001)]))).asExplicit())).toBe('Matrix([[f(0, 0), f(0, 1), f(0, 2)], [f(1, 0), f(1, 1), f(1, 2)], [f(2, 0), f(2, 1), f(2, 2)]])');
  });
  it("FunctionMatrix(n, m, 'lambda i, j: i + j')", () => {
    const [n, m] = symbols('n m');
    expect(sympyStr(FunctionMatrix(n, m, 'lambda i, j: i + j'))).toBe('FunctionMatrix(n, m, Lambda((i, j), i + j))');
  });
  it("(Y**2)[10,10] # So this is evaluated lazily", () => {
    const [i, j] = symbols('i j');
    expect(sympyStr(MatPow(FunctionMatrix(Rational.of(1000n, 1n, { gcd: 1n }), Rational.of(1000n, 1n, { gcd: 1n }), Lambda([i, j], add(i, j))), Rational.of(2n, 1n, { gcd: 1n })).at(10, 10))).toBe('342923500');
  });
});

describe("doctests of sympy.matrices.expressions.fourier", () => {
  it("DFT(3)", () => {
    expect(sympyStr(DFT(Rational.of(3n, 1n, { gcd: 1n })))).toBe('DFT(3)');
  });
  it("DFT(3).as_explicit()", () => {
    expect(sympyStr(DFT(Rational.of(3n, 1n, { gcd: 1n })).asExplicit())).toBe('Matrix([[sqrt(3)/3, sqrt(3)/3, sqrt(3)/3], [sqrt(3)/3, sqrt(3)*exp(-2*I*pi/3)/3, sqrt(3)*exp(2*I*pi/3)/3], [sqrt(3)/3, sqrt(3)*exp(2*I*pi/3)/3, sqrt(3)*exp(-2*I*pi/3)/3]])');
  });
  it("DFT(n).shape", () => {
    const n = new Sym('n');
    const v1 = n;
    expect(sympyMatches([v1, v1], '(n, n)')).toBe(true);
  });
  it("IDFT(3)", () => {
    expect(sympyStr(IDFT(Rational.of(3n, 1n, { gcd: 1n })))).toBe('IDFT(3)');
  });
  it("IDFT(4)*DFT(4)", () => {
    expect(sympyStr(IDFT(Rational.of(4n, 1n, { gcd: 1n })).mul(DFT(Rational.of(4n, 1n, { gcd: 1n }))))).toBe('I');
  });
});

describe("sympy/matrices/expressions/tests/test_fourier.py", () => {
  it("test_dft_creation:17", () => {
    expect(() => DFT(Rational.of(-1n, 1n, { gcd: 1n }))).toThrow(RangeError);
  });
  it("test_dft_creation:18", () => {
    expect(() => DFT(new Float(2))).toThrow(RangeError);
  });
  it("test_dft_creation:24", () => {
    const n = new Sym('n', { integer: false });
    expect(() => DFT(n)).toThrow(RangeError);
  });
  it("test_dft_creation:26", () => {
    const n = new Sym('n', { negative: true });
    expect(() => DFT(n)).toThrow(RangeError);
  });
  it("test_dft:31", () => {
    const v1 = Rational.of(4n, 1n, { gcd: 1n });
    expect(sympyMatches([v1, v1], '(4, 4)')).toBe(true);
  });
  it("test_dft:32", () => {
    expect(sympyStr(ask(Q.unitary(DFT(Rational.of(4n, 1n, { gcd: 1n }))), true))).toBe('True');
  });
  it("test_dft:33", () => {
    expect(sympyStr(abs(I))).toBe('1');
  });
  it("test_dft:34", () => {
    const n = new Sym('n');
    expect(sympyStr(DFT(n).mul(IDFT(n)))).toBe('I');
  });
  it("test_dft:35", () => {
    const [n, i, j] = symbols('n i j');
    expect(sympyStr(DFT(n).at(i, j))).toBe('exp(-2*I*pi/n)**(i*j)/sqrt(n)');
  });
  it("test_dft2:39", () => {
    expect(sympyStr(DFT(Rational.of(1n, 1n, { gcd: 1n })).asExplicit())).toBe('Matrix([[1]])');
  });
  it("test_dft2:40", () => {
    expect(sympyStr(DFT(Rational.of(2n, 1n, { gcd: 1n })).asExplicit())).toBe('Matrix([[sqrt(2)/2, sqrt(2)/2], [sqrt(2)/2, -sqrt(2)/2]])');
  });
  it("test_dft2:41", () => {
    expect(sympyStr(DFT(Rational.of(4n, 1n, { gcd: 1n })).asExplicit())).toBe('Matrix([[1/2, 1/2, 1/2, 1/2], [1/2, -I/2, -1/2, I/2], [1/2, -1/2, 1/2, -1/2], [1/2, I/2, -1/2, -I/2]])');
  });
});

